import os,json
root='.'
out={'top':{},'matches':[]}
for d in ['CONTROL','RUNS','DIAGNOSTICS','LOGS']:
    try:
        out['top'][d]=sorted(os.listdir(d))[:200]
    except Exception as e:
        out['top'][d]={'error':repr(e)}
for base in ['CONTROL','RUNS','DIAGNOSTICS','LOGS']:
    if not os.path.isdir(base): continue
    for dp,ds,fs in os.walk(base):
        rel=os.path.relpath(dp,'.')
        depth=rel.count(os.sep)
        if depth>5:
            ds[:]=[]
            continue
        for n in fs:
            p=os.path.join(dp,n)
            low=p.lower()
            if ('892' in low or 'queue' in low or 'run_state' in low or 'postrun' in low or 'premiere_validation' in low or 'regression' in low or 'timeline_audit' in low or 'censor' in low):
                try:
                    st=os.stat(p)
                    out['matches'].append({'path':p.replace('\\','/'),'size':st.st_size,'mtime':st.st_mtime})
                except Exception as e:
                    out['matches'].append({'path':p.replace('\\','/'),'error':repr(e)})
print(json.dumps(out,ensure_ascii=False))
